    final int bitPos;
    final int val;
    final int pos;
    public static final int length = 33;

    CharacterTemporaryStat(int val) {
        this.bitPos = val;
        this.val = 1 << (31 - bitPos % 32);
        this.pos = bitPos / 32;
    }

    public static CharacterTemporaryStat getByBitPos(int bitPos) {
        return Arrays.stream(values()).filter(v -> v.getBitPos() == bitPos).findAny().orElse(null);
    }

    public static CharacterTemporaryStat getByVal(int val) {
        return Arrays.stream(values()).filter(v -> v.getVal() == val).findAny().orElse(null);
    }

    public boolean isEncodeInt() {
        switch (this) {
            case CarnivalDefence:
            case SpiritLink:
            case DojangLuckyBonus:
            case SoulGazeCriDamR:
            case PowerTransferGauge:
            case ReturnTeleport:
            case ShadowPartner:
            case SetBaseDamage:
            case ImmuneBarrier:
            case QuiverCatridge:
            case NaviFlying:
            case Dance:
            case SetBaseDamageByBuff:
            case DotHealHPPerSecond:
            case DotHealMPPerSecond:
            case IncMaxDamage:
            case GrabbedByMob:
            case MarkingStella:
            case MagnetArea:
            case PairingUser:
            case MegaSmasher:
            case VampDeath:
            case FifthAdvWarriorShield:
            case RidingExpireInfoSave:
            case RWBarrier:
            case SiphonVitalityBarrier:
                return true;
            default:
                return false;
        }
    }

    public boolean isIndie() {
        return ordinal() < IndieStatCount.ordinal();
    }

    public int getVal() {
        return val;
    }

    public int getPos() {
        return pos;
    }

    public int getOrder() {
        return localOrders.indexOf(this);
    }

